    if last_tag:
        cmd = f"git log {last_tag}..HEAD --pretty=format:'%H|%s|%b'"
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, cwd='/app')
        commits = []
        output = result.stdout.strip()
        if output:
            for line in output.split('\n'):
                if line:
                    parts = line.split('|')
                    if len(parts) >= 2:
                        commits.append({
                            'hash': parts[0],
                            'subject': parts[1],
                            'body': parts[2] if len(parts) > 2 else ''
                        })
        return commits
    else:
        cmd = "git log --pretty=format:'%H|%s|%b'"
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, cwd='/app')
        commits = []
