def get_files_in_commit(commit_hash):
    """Get list of files modified in a commit"""
    cmd = f"git show -s --name-only --format='' {commit_hash}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, cwd='/app')
    files = result.stdout.strip().split('\n') if result.stdout.strip() else []
    files = [f for f in files if f]
    return files

def parse_commit_message(msg):
    """Parse commit message in format: type(scope): description
    msg is the full message text (subject + body)
    Returns dict with type, scope, description, bump or None"""
    match = re.match(r'^(\w+)\(([^)]+)\):\s*(.*)$', msg.strip())
    if match:
