        scope = match.group(2)
        description = match.group(3)
        if "BREAKING CHANGE" in msg:
            bump = "MAJOR"
        elif commit_type == "feat":
            bump = "MINOR"
        elif commit_type == "fix":
            bump = "PATCH"
