    final_bumps = {}  # pkg -> final bump level string
    # For packages with direct changes, use their direct bump
    for pkg in direct_bumps:
        if direct_bumps[pkg]:
            final_bumps[pkg] = direct_bumps[pkg]
    # For packages without direct changes but in will_be_bumped, they get PATCH
    for pkg in will_be_bumped:
        if pkg not in final_bumps:
            final_bumps[pkg] = 'PATCH'

