    for pkg_name in final_bumps:
        # Read current VERSION
        version_path = f"/app/packages/{pkg_name}/VERSION"
        with open(version_path, 'r') as f:
            old_version = f.read().strip()

        # Calculate new version
        new_version = increment_version(old_version, final_bumps[pkg_name])

        # Write new VERSION
        with open(version_path, 'w') as f:
            f.write(new_version + '\n')

        # Prepare CHANGELOG.md content
        changelog_path = f"/app/packages/{pkg_name}/CHANGELOG.md"
        direct_commits = package_commits.get(pkg_name, [])
        has_direct = len(direct_commits) > 0

        lines = []
        lines.append(f"## {new_version} ({today_date})")

        if has_direct:
            feat_items = []
            fix_items = []
            for c in direct_commits:
                if c['type'] == 'feat':
                    feat_items.append(c['description'])
                elif c['type'] == 'fix':
